// Дополнительные алгоритмы умного подбора.
function getSmartEligibleMovies() {
  return moviesDatabase.filter(movie => {
    const rating = Number.parseFloat(movie.rating);
    const year = Number.parseInt(movie.year, 10);
    const duration = typeof movie.duration === "number"
      ? movie.duration
      : Number.parseFloat(String(movie.duration || "").replace(",", "."));
    const description = String(movie.longDesc || movie.desc || movie.description || "").trim();

    return Boolean(
      movie.title && Number.isFinite(rating) && rating > 0 && rating <= 10 &&
      Number.isInteger(year) && year >= 1888 && year <= new Date().getFullYear() &&
      Number.isFinite(duration) && duration > 0 &&
      description.length >= 20 && !description.startsWith("Фильм из категории")
    );
  });
}

function smartMovieSummary(movie) {
  const rating = Number.parseFloat(movie.rating).toFixed(1);
  const duration = typeof movie.duration === "number"
    ? movie.duration
    : Number.parseFloat(String(movie.duration || "").replace(",", "."));
  return `«${movie.title}» (${movie.year}) · ⭐ ${rating} · ⏱ ${duration} мин.`;
}

window.pickMovieByMood = function () {
  const mood = document.getElementById("moodSelect")?.value;
  const result = document.getElementById("moodResult");
  if (!result) return;

  const genresByMood = {
    adventure: ["action", "detective"],
    thoughtful: ["drama", "detective"],
    light: ["comedy"],
    romantic: ["romance"],
    fantasy: ["sci-fi"]
  };
  const allowedGenres = genresByMood[mood] || [];
  const matches = getSmartEligibleMovies().filter(movie => allowedGenres.includes(movie.genre));

  if (!matches.length) {
    result.textContent = "Не удалось найти фильм с полными данными для выбранного настроения.";
    result.className = "result-placeholder result-error";
    return;
  }

  const movie = matches[Math.floor(Math.random() * matches.length)];
  result.textContent = `🎬 Вам подойдёт фильм: ${smartMovieSummary(movie)} ${String(movie.longDesc || movie.desc || movie.description).trim()}`;
  result.className = "result-placeholder result-success";
};

window.pickDoubleFeature = function () {
  const input = document.getElementById("doubleFeatureLimit");
  const result = document.getElementById("doubleFeatureResult");
  if (!input || !result) return;

  const limit = Number(input.value);
  if (!Number.isInteger(limit) || limit < 60 || limit > 600) {
    result.textContent = "Укажи целое время от 60 до 600 минут.";
    result.className = "result-placeholder result-error";
    return;
  }

  const candidates = getSmartEligibleMovies().map(movie => ({
    movie,
    duration: typeof movie.duration === "number"
      ? movie.duration
      : Number.parseFloat(String(movie.duration || "").replace(",", ".")),
    rating: Number.parseFloat(movie.rating)
  }));

  let bestPair = null;
  for (let i = 0; i < candidates.length; i++) {
    for (let j = i + 1; j < candidates.length; j++) {
      const first = candidates[i];
      const second = candidates[j];
      const totalDuration = first.duration + second.duration;
      if (totalDuration > limit) continue;

      const ratingTotal = first.rating + second.rating;
      if (!bestPair || ratingTotal > bestPair.ratingTotal ||
          (ratingTotal === bestPair.ratingTotal && totalDuration > bestPair.totalDuration)) {
        bestPair = { first, second, ratingTotal, totalDuration };
      }
    }
  }

  if (!bestPair) {
    result.textContent = `Не нашлось двух фильмов с полными данными в лимит ${limit} минут. Увеличь время.`;
    result.className = "result-placeholder result-error";
    return;
  }

  result.textContent = `🍿 Киносеанс на ${bestPair.totalDuration} мин.: ${smartMovieSummary(bestPair.first.movie)} + ${smartMovieSummary(bestPair.second.movie)}.`;
  result.className = "result-placeholder result-success";
};

