const genreNames = { "sci-fi": "фантастика", action: "боевик", drama: "драма", comedy: "комедия", detective: "детектив", romance: "мелодрама" };
let nextMovieId = moviesDatabase.length + 1;
const knownMovieTitles = new Set(moviesDatabase.map(movie => movie.title));
Object.entries(extraMovieTitles).forEach(([genre, titles]) => {
  titles.split("|").forEach(title => {
    if (knownMovieTitles.has(title)) return;
    knownMovieTitles.add(title);
    moviesDatabase.push({
      id: nextMovieId++,
      genre,
      title,
      rating: "—",
      year: "—",
      duration: null,
      food: genre === "sci-fi" ? "popcorn" : genre === "drama" || genre === "romance" ? "tea" : "pizza",
      desc: `Фильм из категории «${genreNames[genre]}». Подробности о выпуске и хронометраже не указаны.`,
      longDesc: `«${title}» добавлен в каталог как фильм жанра «${genreNames[genre]}». Дата выпуска, рейтинг и длительность в этой карточке не указаны.`
    });
  });
});

// Распределяем фильмы из подборки по отдельным жанрам, включая уже существующие записи.
const requestedGenreByTitle = new Map([
  ["Вырисуйся", "detective"], ["Код Да Винчи", "detective"], ["Ангелы и Демоны", "detective"],
  ["Инферно", "detective"], ["Сокровище нации", "detective"], ["Сокровище нации: Книга тайн", "detective"],
  ["Ван Хельсинг", "detective"], ["Хеллбой: Герой из пекла", "detective"],
  ["Хеллбой II: Золотая армия", "detective"], ["Престиж", "detective"],
  ["Дневник памяти", "romance"], ["Загадочная история Бенджамина Баттона", "romance"],
  ["Дом у озера", "romance"], ["Вечное сияние чистого разума", "romance"],
  ["Бойфренд из будущего", "romance"], ["Запах женщины", "romance"],
  ["Красотка", "romance"], ["До встречи с тобой", "romance"],
  ["Бойцовский класс", "drama"], ["Тюрьма общего режима", "drama"],
  ["Зеленая книга", "drama"], ["Облачный атлас", "drama"], ["Шоу Трумана", "drama"]
]);
moviesDatabase.forEach(movie => {
  const genre = requestedGenreByTitle.get(movie.title);
  if (genre) {
    movie.genre = genre;
    movie.food = genre === "detective" ? "pizza" : "tea";
  }
});

