const normalizeMovieTitle = title => title.toLocaleLowerCase("ru").replace(/ё/g, "е").replace(/[^a-zа-я0-9]+/gi, "");
const suppliedMetadataByTitle = new Map(suppliedMovieMetadata.map(([title, rating, description]) => [normalizeMovieTitle(title), { rating, description }]));
const metadataTitleAliases = new Map([
  ["Крестный отец", "Крёстный отец"],
  ["Зеленая миля", "Зелёная миля"],
  ["Звездные войны: Новая надежда", "Звёздные войны: Новая надежда"],
  ["Звездные войны: Империя наносит ответный удар", "Звёздные войны: Империя наносит ответный удар"],
  ["Звездные войны: Возвращение джедая", "Звёздные войны: Возвращение джедая"],
  ["Звёздные войны: Новая надежда", "Звездные войны: Эпизод 4 — Новая надежда"],
  ["Звёздные войны: Империя наносит ответный удар", "Звездные войны: Эпизод 5 — Империя наносит ответный удар"],
  ["Звёздные войны: Возвращение джедая", "Звездные войны: Эпизод 6 — Возвращение джедая"],
  ["ВАЛЛ-И", "ВАЛЛ·И"]
]);

moviesDatabase.forEach(movie => {
  const lookupTitle = metadataTitleAliases.get(movie.title) || movie.title;
  const metadata = suppliedMetadataByTitle.get(normalizeMovieTitle(lookupTitle));
  if (!metadata) return;

  movie.rating = metadata.rating.toFixed(1);
  movie.desc = metadata.description;
  movie.longDesc = metadata.description;
  movie.ratingIsEstimated = false;
});

