finalNewMovieBatch.forEach(film => {
  const existing = moviesDatabase.find(movie => normalizeMovieTitle(movie.title) === normalizeMovieTitle(film.title));
  const record = existing || {
    id: nextMovieId++,
    food: film.genre === "romance" || film.genre === "drama" ? "tea" : "pizza"
  };
  Object.assign(record, {
    genre: film.genre,
    title: film.title,
    year: film.year,
    rating: film.rating.toFixed(1),
    duration: film.duration,
    desc: film.description,
    longDesc: film.description
  });
  if (!existing) moviesDatabase.push(record);
});

const addedMovieTitles = new Set(moviesDatabase.map(movie => normalizeMovieTitle(movie.title)));
let addedMovieCount = 0;
(window.additionalMovieData || []).forEach(movie => {
  if (addedMovieCount >= 200) return;
  const titleKey = normalizeMovieTitle(movie.title);
  const translation = (window.additionalMovieTranslations || {})[movie.title] || {};
  const localizedTitle = String(translation.title || movie.title).trim();
  const localizedTitleKey = normalizeMovieTitle(localizedTitle);
  const rating = Number.parseFloat(movie.rating);
  const year = Number.parseInt(movie.year, 10);
  const duration = Number.parseInt(movie.duration, 10);
  let description = String(translation.description || movie.description || "").trim();
  if (movie.title === "Hachi: A Dog's Tale") {
    description = "История профессора, который принимает в дом брошенную собаку и постепенно становится для неё самым близким человеком. Их ежедневные встречи перерастают в преданную дружбу, проверенную разлукой и временем. Фильм рассказывает о верности и привязанности, которые не требуют слов.";
  }
  if (!titleKey || addedMovieTitles.has(titleKey) || addedMovieTitles.has(localizedTitleKey) || !Number.isFinite(rating) || rating <= 0 || rating > 10 ||
      !Number.isInteger(year) || year < 1888 || year > new Date().getFullYear() ||
      !Number.isInteger(duration) || duration <= 0 || description.length < 40) return;

  moviesDatabase.push({
    id: nextMovieId++,
    genre: movie.genre,
    title: localizedTitle,
    rating: rating.toFixed(1),
    year: String(year),
    duration,
    food: movie.genre === "sci-fi" || movie.genre === "comedy" ? "popcorn" : movie.genre === "drama" || movie.genre === "romance" ? "tea" : "pizza",
    desc: description,
    longDesc: description
  });
  addedMovieTitles.add(titleKey);
  addedMovieTitles.add(localizedTitleKey);
  addedMovieCount++;
});

const hasMovieDetails = movie => {
  const rating = Number.parseFloat(movie.rating);
  const year = String(movie.year || "").trim();
  const hasRating = Number.isFinite(rating) && rating > 0 && rating <= 10;
  const hasReleaseDate = /^(18|19|20)\d{2}$/.test(year) || Boolean(String(movie.releaseDate || "").trim());
  const hasTrailer = [movie.trailerId, movie.trailer, movie.trailerUrl]
    .some(value => value != null && String(value).trim() && !["—", "-"].includes(String(value).trim()));
  const hasDescription = [movie.longDesc, movie.desc, movie.description]
    .some(value => {
      const description = String(value || "").trim();
      return description.length >= 20 &&
        !/^(?:Фильм из категории|«.+» добавлен в каталог как фильм жанра)/i.test(description) &&
        !/^описание (не указано|отсутствует)$/i.test(description);
    });

  return hasRating || hasReleaseDate || hasTrailer || hasDescription;
};
moviesDatabase.splice(0, moviesDatabase.length, ...moviesDatabase.filter(hasMovieDetails));

const movieCompletenessScore = movie =>
  Number(Number.isFinite(Number.parseFloat(movie.rating)) && Number.parseFloat(movie.rating) > 0) +
  Number(/^(18|19|20)\d{2}$/.test(String(movie.year || "").trim())) +
  Number(Number.isFinite(Number(movie.duration)) && Number(movie.duration) > 0) +
  Number([movie.longDesc, movie.desc, movie.description].some(value => {
    const description = String(value || "").trim();
    return description.length >= 20 && !/^(?:Фильм из категории|«.+» добавлен в каталог как фильм жанра)/i.test(description);
  })) +
  Number([movie.trailerId, movie.trailer, movie.trailerUrl].some(value => value != null && String(value).trim() && !["—", "-"].includes(String(value).trim())));
const uniqueMoviesByTitle = new Map();
moviesDatabase.forEach(movie => {
  const titleKey = normalizeMovieTitle(movie.title);
  const existing = uniqueMoviesByTitle.get(titleKey);
  if (!existing) {
    uniqueMoviesByTitle.set(titleKey, movie);
    return;
  }

  const preferred = movieCompletenessScore(movie) > movieCompletenessScore(existing) ? movie : existing;
  uniqueMoviesByTitle.set(titleKey, { ...preferred, id: existing.id });
});
moviesDatabase.splice(0, moviesDatabase.length, ...uniqueMoviesByTitle.values());

const additionalMovieTranslations = window.additionalMovieTranslations || {};
const translationsByLocalizedTitle = new Map(Object.values(additionalMovieTranslations)
  .filter(translation => translation?.title)
  .map(translation => [normalizeMovieTitle(translation.title), translation]));
moviesDatabase.forEach(movie => {
  const translation = additionalMovieTranslations[movie.title] || translationsByLocalizedTitle.get(normalizeMovieTitle(movie.title));
  if (!translation) return;
  if (translation.title) movie.title = translation.title;
  if (translation.description) {
    movie.desc = translation.description;
    movie.longDesc = translation.description;
  }
});

// Состояние фильтров и список избранного
let currentGenre = "all";
let currentSort = "rating";
let showWatchlistOnly = false;
let sharedMovieIds = null;
const sharedParams = new URLSearchParams(window.location.search);
const sharedMovieParam = sharedParams.get("share") || sharedParams.get("tracks");
if (sharedMovieParam) {
  const ids = [...new Set(sharedMovieParam.split(",").map(Number).filter(id => Number.isSafeInteger(id) && id > 0))];
  if (ids.length) sharedMovieIds = ids;
}

function loadWatchlist() {
  try {
    const saved = JSON.parse(localStorage.getItem("cineNavigatorWatchlist") || "[]");
    return Array.isArray(saved) ? saved.filter(id => moviesDatabase.some(movie => movie.id === id)) : [];
  } catch {
    return [];
  }
}

let watchlist = loadWatchlist();

function saveWatchlist() {
  try {
    localStorage.setItem("cineNavigatorWatchlist", JSON.stringify(watchlist));
  } catch {
    // Избранное останется доступным до перезагрузки, если хранилище отключено.
  }
}

function updateWatchlistControl() {
  const count = document.getElementById("watchlistCount");
  const button = document.getElementById("watchlistFilterBtn");
  if (count) count.textContent = watchlist.length;
  if (button) {
    button.classList.toggle("active", showWatchlistOnly);
    button.setAttribute("aria-pressed", String(showWatchlistOnly));
  }
}

window.toggleWatchlistFilter = function () {
  showWatchlistOnly = !showWatchlistOnly;
  updateWatchlistControl();
  applyMovieFilters();
};

window.toggleWatchlist = function (movieId) {
  if (watchlist.includes(movieId)) {
    watchlist = watchlist.filter(id => id !== movieId);
  } else {
    watchlist.push(movieId);
  }
  saveWatchlist();
  updateWatchlistControl();
  applyMovieFilters();
};

window.shareWatchlist = async function () {
  const result = document.getElementById("watchlistShareResult");
  const linkInput = document.getElementById("watchlistShareLink");
  const status = document.getElementById("watchlistShareStatus");
  if (!result || !linkInput || !status) return;
  result.hidden = false;

  const validIds = [...new Set(watchlist.filter(id => moviesDatabase.some(movie => movie.id === id)))];
  if (!validIds.length) {
    linkInput.value = "";
    status.textContent = "Добавь фильмы в избранное, чтобы создать подборку.";
    return;
  }

  const shareUrl = new URL(window.location.href);
  shareUrl.searchParams.delete("tracks");
  shareUrl.searchParams.set("share", validIds.join(","));
  linkInput.value = shareUrl.href;
  try {
    await navigator.clipboard.writeText(linkInput.value);
    status.textContent = "Ссылка скопирована. Отправь её другу.";
  } catch (_) {
    status.textContent = "Ссылка готова. Нажми на поле, чтобы выделить и скопировать её.";
  }
};

window.clearSharedPlaylist = function () {
  sharedMovieIds = null;
  const clearButton = document.getElementById("clearSharedPlaylist");
  if (clearButton) clearButton.hidden = true;
  const shareUrl = new URL(window.location.href);
  shareUrl.searchParams.delete("share");
  shareUrl.searchParams.delete("tracks");
  window.history.replaceState(null, "", shareUrl);
  applyMovieFilters();
};

updateWatchlistControl();

const toolsTabButtons = [...document.querySelectorAll("[data-tools-tab]")];
window.switchToolsTab = function (tabName, shouldFocus = false) {
  const activeTab = toolsTabButtons.find(button => button.dataset.toolsTab === tabName);
  if (!activeTab) return;

  toolsTabButtons.forEach(button => {
    const isActive = button === activeTab;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-selected", String(isActive));
    button.tabIndex = isActive ? 0 : -1;
  });
  document.querySelectorAll("[data-tools-group]").forEach(card => {
    card.hidden = card.dataset.toolsGroup !== tabName;
  });
  document.getElementById("smartToolsPanel")?.setAttribute("aria-labelledby", activeTab.id);
  if (shouldFocus) activeTab.focus();
};

document.querySelector('[role="tablist"][aria-label="Разделы умного подбора"]')?.addEventListener("keydown", event => {
  const currentIndex = toolsTabButtons.indexOf(event.target.closest("[data-tools-tab]"));
  if (currentIndex < 0) return;

  let nextIndex = currentIndex;
  if (event.key === "ArrowRight") nextIndex = (currentIndex + 1) % toolsTabButtons.length;
  else if (event.key === "ArrowLeft") nextIndex = (currentIndex - 1 + toolsTabButtons.length) % toolsTabButtons.length;
  else if (event.key === "Home") nextIndex = 0;
  else if (event.key === "End") nextIndex = toolsTabButtons.length - 1;
  else return;

  event.preventDefault();
  window.switchToolsTab(toolsTabButtons[nextIndex].dataset.toolsTab, true);
});

const uiSettings = document.querySelector(".ui-settings");
if (uiSettings) {
  document.addEventListener("pointerdown", event => {
    if (uiSettings.open && !uiSettings.contains(event.target)) uiSettings.open = false;
  });
  document.addEventListener("keydown", event => {
    if (event.key === "Escape" && uiSettings.open) {
      uiSettings.open = false;
      uiSettings.querySelector("summary")?.focus();
    }
  });
}

// --- НАВИГАЦИЯ МЕЖДУ СЕКЦИЯМИ ---
window.switchSection = function (sectionName) {
  const sections = {
    about: "sectionAbout",
    catalog: "sectionCatalog",
    tools: "sectionTools",
    guide: "sectionGuide"
  };
  if (!sections[sectionName]) return;

  // Скрываем все разделы
  Object.values(sections).forEach(id => {
    const el = document.getElementById(id);
    if (el) el.style.display = "none";
  });

  // Обнуляем активные кнопки навигации
  document.querySelectorAll(".nav-btn").forEach(btn => btn.classList.remove("active"));

  // Включаем нужный раздел
  const targetSection = document.getElementById(sections[sectionName]);
  const targetButton = document.getElementById(`btn-${sectionName}`);

  if (targetSection) targetSection.style.display = "block";
  if (targetButton) targetButton.classList.add("active");
  document.querySelectorAll("[data-dock]").forEach(button => {
    button.classList.toggle("is-active", button.dataset.dock === sectionName);
  });
  document.dispatchEvent(new CustomEvent("cine:section-change", { detail: { section: sectionName } }));

  // Если зашли в каталог — сразу запускаем фильтрацию и отрисовку
  if (sectionName === "catalog") applyMovieFilters();

  if (targetSection && window.matchMedia("(max-width: 768px)").matches) {
    requestAnimationFrame(() => requestAnimationFrame(() => {
      targetSection.scrollIntoView({
        behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth",
        block: "start"
      });
    }));
  }
};

// --- СМАРТ-ФИЛЬТРАЦИЯ И СОРТИРОВКА КАТАЛОГА ---
const genreTabs = document.getElementById("genreTabs");
const genreScrollPrevious = document.getElementById("genreScrollPrevious");
const genreScrollNext = document.getElementById("genreScrollNext");
const updateGenreScrollControls = () => {
  if (!genreTabs || !genreScrollPrevious || !genreScrollNext) return;
  const maxScroll = genreTabs.scrollWidth - genreTabs.clientWidth;
  const canScroll = maxScroll > 4;
  genreScrollPrevious.hidden = !canScroll || genreTabs.scrollLeft <= 2;
  genreScrollNext.hidden = !canScroll || genreTabs.scrollLeft >= maxScroll - 2;
};

const scrollGenreTabs = direction => {
  if (!genreTabs) return;
  const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const distance = genreTabs.clientWidth * .75 * direction;
  if (reducedMotion) {
    genreTabs.style.scrollBehavior = "auto";
    genreTabs.scrollLeft += distance;
  } else {
    genreTabs.scrollBy({ left: distance, behavior: "smooth" });
  }
};
genreScrollPrevious?.addEventListener("click", () => scrollGenreTabs(-1));
genreScrollNext?.addEventListener("click", () => scrollGenreTabs(1));
genreTabs?.addEventListener("scroll", updateGenreScrollControls, { passive: true });
window.addEventListener("resize", updateGenreScrollControls, { passive: true });
document.addEventListener("cine:section-change", event => {
  if (event.detail?.section === "catalog") window.requestAnimationFrame(updateGenreScrollControls);
});

window.filterGenre = function (genre) {
  currentGenre = genre;
  document.querySelectorAll(".tab-btn").forEach(btn => btn.classList.remove("active"));
  
  const activeBtn = document.getElementById(`genre-${genre}`);
  if (activeBtn) {
    activeBtn.classList.add("active");
    const targetLeft = activeBtn.offsetLeft - (genreTabs.clientWidth - activeBtn.offsetWidth) / 2;
    const maxScroll = genreTabs.scrollWidth - genreTabs.clientWidth;
    const left = Math.max(0, Math.min(maxScroll, targetLeft));
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      genreTabs.style.scrollBehavior = "auto";
      genreTabs.scrollLeft = left;
    } else {
      genreTabs.scrollTo({ left, behavior: "smooth" });
    }
  }
  window.requestAnimationFrame(updateGenreScrollControls);

  applyMovieFilters();
};

window.sortMovies = function (sortType) {
  currentSort = sortType;
  document.querySelectorAll(".sort-btn").forEach(btn => btn.classList.remove("active"));

  const activeBtn = document.getElementById(`sort-${sortType}`);
  if (activeBtn) activeBtn.classList.add("active");

  applyMovieFilters();
};

document.addEventListener("keydown", event => {
  const search = document.getElementById("movieSearch");
  if (!search || document.querySelector(".movie-modal.is-open, .session-sheet.is-open, #antiSporModal.is-open")) return;

  if ((event.key === "/" && !event.ctrlKey && !event.metaKey && !event.altKey) ||
      ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k")) {
    const target = event.target;
    if (target instanceof HTMLElement && target.matches("input, textarea, select, [contenteditable='true']")) return;
    event.preventDefault();
    search.focus();
  } else if (event.key === "Escape" && document.activeElement === search && search.value) {
    search.value = "";
    applyMovieFilters();
  }
});

function getSearchCriteria(rawQuery) {
  const query = String(rawQuery || "").trim().toLocaleLowerCase("ru");
  const criteria = { text: "", decade: null, year: null, minRating: null, maxRating: null, minRatingExclusive: false, maxRatingExclusive: false, genres: null, keywords: [] };

  const decadeMatch = query.match(/(?:^|\s)(\d{2})\s*(?:s|[-–]?е)(?:\s|$)/i);
  if (decadeMatch) {
    const decade = Number(decadeMatch[1]);
    criteria.decade = decade >= 30 ? 1900 + decade : 2000 + decade;
  }

  const yearMatch = query.match(/\b(18\d{2}|19\d{2}|20\d{2})\b/);
  if (yearMatch) criteria.year = Number(yearMatch[1]);

  const ratingMatch = query.match(/(?:^|\s)([<>]=?)\s*(\d(?:[.,]\d+)?)|(?:^|\s)(\d(?:[.,]\d+)?)\s*\+/);
  if (ratingMatch) {
    if (ratingMatch[1]) {
      const value = Number(ratingMatch[2].replace(",", "."));
      if (ratingMatch[1].startsWith(">")) {
        criteria.minRating = value;
        criteria.minRatingExclusive = ratingMatch[1] === ">";
      } else {
        criteria.maxRating = value;
        criteria.maxRatingExclusive = ratingMatch[1] === "<";
      }
    } else {
      criteria.minRating = Number(ratingMatch[3].replace(",", "."));
    }
  }

  const moodKeywords = {
    light: ["расслабиться", "вечер", "легкое", "лёгкое", "отдохнуть"],
    thoughtful: ["подумать", "мозг", "закрученный", "загадка"],
    space: ["космос", "космический", "планета"],
    aviation: ["самолет", "самолёт", "авиация", "пилот", "летчик", "лётчик"]
  };
  const matchedMoods = Object.entries(moodKeywords)
    .filter(([, words]) => words.some(word => query.includes(word)))
    .map(([mood]) => mood);

  if (matchedMoods.includes("light")) criteria.genres = ["comedy"];
  if (matchedMoods.includes("thoughtful")) criteria.genres = ["sci-fi", "detective"];
  if (matchedMoods.includes("space")) criteria.genres = ["sci-fi"];
  if (matchedMoods.includes("aviation")) {
    criteria.keywords = ["авиац", "самолет", "самолёт", "пилот", "летчик", "лётчик", "космос", "космонавт", "астронавт"];
  }

  criteria.text = normalizeMovieTitle(query
    .replace(/(?:^|\s)\d{2}\s*(?:s|[-–]?е)(?=\s|$)/ig, " ")
    .replace(/\b(?:18\d{2}|19\d{2}|20\d{2})\b/g, " ")
    .replace(/(?:^|\s)[<>]=?\s*\d(?:[.,]\d+)?|(?:^|\s)\d(?:[.,]\d+)?\s*\+/g, " ")
    .replace(/расслабиться|вечер|легкое|лёгкое|отдохнуть|подумать|мозг|закрученный|загадка|космос|космический|планета|самолет|самолёт|авиация|пилот|летчик|лётчик/ig, " "));
  return criteria;
}

function matchesSearchCriteria(movie, criteria) {
  const year = Number.parseInt(movie.year, 10);
  const rating = Number.parseFloat(movie.rating);
  if (criteria.decade !== null && (!Number.isInteger(year) || Math.floor(year / 10) * 10 !== criteria.decade)) return false;
  if (criteria.year !== null && year !== criteria.year) return false;
  if (criteria.minRating !== null && (!Number.isFinite(rating) ||
      (criteria.minRatingExclusive ? rating <= criteria.minRating : rating < criteria.minRating))) return false;
  if (criteria.maxRating !== null && (!Number.isFinite(rating) ||
      (criteria.maxRatingExclusive ? rating >= criteria.maxRating : rating > criteria.maxRating))) return false;
  if (criteria.genres && !criteria.genres.includes(movie.genre)) return false;
  if (criteria.keywords.length) {
    const haystack = `${movie.title} ${movie.longDesc || movie.desc || movie.description || ""}`.toLocaleLowerCase("ru");
    const aviationTitle = normalizeMovieTitle(movie.title);
    const knownAviationTitles = ["топганмэверик", "чудонагудзоне", "авиатор", "экипаж"];
    const matchesKnownAviationTitle = knownAviationTitles.some(title => aviationTitle.includes(title));
    if (!matchesKnownAviationTitle && !criteria.keywords.some(keyword => haystack.includes(keyword))) return false;
  }
  if (criteria.text && !normalizeMovieTitle(movie.title).includes(criteria.text)) return false;
  return true;
}

function applyMovieFilters() {
  // Спецзапросы (десятилетие, год/рейтинг или настроение) ищут по всему каталогу.
  const searchInput = document.getElementById("movieSearch");
  const rawQuery = searchInput ? searchInput.value.trim() : "";
  const criteria = getSearchCriteria(rawQuery);
  const hasSpecialCriteria = criteria.decade !== null || criteria.year !== null ||
    criteria.minRating !== null || criteria.maxRating !== null || criteria.genres || criteria.keywords.length;
  let filtered = sharedMovieIds
    ? moviesDatabase.filter(movie => sharedMovieIds.includes(movie.id))
    : rawQuery || currentGenre === "all" || hasSpecialCriteria
      ? [...moviesDatabase]
      : moviesDatabase.filter(movie => movie.genre === currentGenre);

  if (rawQuery) {
    filtered = filtered.filter(movie => matchesSearchCriteria(movie, criteria));
  }
  if (sharedMovieIds && currentGenre !== "all") {
    filtered = filtered.filter(movie => movie.genre === currentGenre);
  }
  if (showWatchlistOnly && !sharedMovieIds) {
    filtered = filtered.filter(movie => watchlist.includes(movie.id));
  }

  // 2. Сортируем
  if (currentSort === "rating") {
    filtered.sort((a, b) => {
      const ratingA = Number.parseFloat(a.rating);
      const ratingB = Number.parseFloat(b.rating);
      if (!Number.isFinite(ratingA)) return Number.isFinite(ratingB) ? 1 : 0;
      if (!Number.isFinite(ratingB)) return -1;
      return ratingB - ratingA;
    });
  } else if (currentSort === "year") {
    filtered.sort((a, b) => {
      const yearA = Number.parseInt(a.year, 10);
      const yearB = Number.parseInt(b.year, 10);
      if (!Number.isFinite(yearA)) return Number.isFinite(yearB) ? 1 : 0;
      if (!Number.isFinite(yearB)) return -1;
      return yearB - yearA;
    });
  } else if (currentSort === "duration") {
    filtered.sort((a, b) => {
      const durationA = getMovieDuration(a);
      const durationB = getMovieDuration(b);
      if (!Number.isFinite(durationA)) return Number.isFinite(durationB) ? 1 : 0;
      if (!Number.isFinite(durationB)) return -1;
      return durationA - durationB;
    });
  }

  renderMovies(filtered);
}

window.pickRandomMovie = function () {
  const result = document.getElementById("quickPickResult");
  const eligibleMovies = moviesDatabase.filter(isCompleteMovie);
  if (!result) return;
  if (eligibleMovies.length === 0) {
    result.textContent = "Пока нет фильмов с полными данными для случайного подбора.";
    result.classList.add("is-visible");
    return;
  }

  const movie = eligibleMovies[Math.floor(Math.random() * eligibleMovies.length)];
  result.textContent = `🎬 Случайный выбор: ${formatMovieRecommendation(movie)}`;
  result.classList.add("is-visible");
};

function getMovieDescription(movie) {
  return String(movie.longDesc || movie.desc || movie.description || "").trim();
}

function getMovieDuration(movie) {
  const duration = typeof movie.duration === "number"
    ? movie.duration
    : Number.parseFloat(String(movie.duration || "").replace(",", "."));
  return Number.isFinite(duration) ? duration : NaN;
}

function isCompleteMovie(movie) {
  const description = getMovieDescription(movie);
  const rating = Number.parseFloat(movie.rating);
  const year = Number.parseInt(movie.year, 10);
  const duration = getMovieDuration(movie);

  return Boolean(
    typeof movie.title === "string" && movie.title.trim() &&
    Number.isFinite(rating) && rating > 0 && rating <= 10 &&
    description.length >= 80 && !description.startsWith("Фильм из категории") &&
    Number.isInteger(year) && year >= 1888 && year <= new Date().getFullYear() &&
    Number.isFinite(duration) && duration > 0
  );
}

function formatMovieRecommendation(movie) {
  const rating = Number.parseFloat(movie.rating);
  const year = Number.parseInt(movie.year, 10);
  const duration = getMovieDuration(movie);
  return `«${movie.title}» — ${year} г. · ⭐ ${rating.toFixed(1)} · ⏱ ${duration} мин.`;
}

const MOVIE_INITIAL_BATCH_SIZE = 24;
const MOVIE_NEXT_BATCH_SIZE = 20;
let movieLoadObserver = null;
let movieLoadSentinel = null;
let movieScrollFallback = null;

function getMegogoSearchUrl(movie) {
  const search = new URL("https://www.google.com/search");
  search.searchParams.set("q", `site:megogo.net ${movie.title || ""} ${movie.year || ""}`);
  return search.href;
}

function getNetflixSearchUrl(movie) {
  const originalTitle = String(movie.originalTitle || movie.original_title || movie.title || "").trim();
  const search = new URL("https://www.google.com/search");
  search.searchParams.set("q", `site:netflix.com ${originalTitle} ${movie.year || ""}`);
  return search.href;
}

function getLegalViewingSearchUrl(movie) {
  const search = new URL("https://www.google.com/search");
  search.searchParams.set("q", `${movie.title || ""} ${movie.year || ""} легально смотреть онлайн купить или арендовать`);
  return search.href;
}

function renderMovieCard(movie) {
  const genreLabels = { "sci-fi": "Фантастика", action: "Боевик", drama: "Драма", comedy: "Комедия", detective: "Детектив", romance: "Мелодрама" };
  const parsedYear = Number.parseInt(movie.year, 10);
  const year = Number.isInteger(parsedYear) && parsedYear >= 1888 && parsedYear <= new Date().getFullYear() ? parsedYear : null;
  const parsedRating = Number.parseFloat(movie.rating);
  const rating = Number.isFinite(parsedRating) && parsedRating > 0 && parsedRating <= 10 ? parsedRating.toFixed(1) : null;
  const parsedDuration = Number.parseFloat(String(movie.duration ?? "").replace(",", "."));
  const duration = Number.isFinite(parsedDuration) && parsedDuration > 0 ? parsedDuration : null;
  return `
    <article class="car-card" data-movie-id="${movie.id}">
      <div class="car-visual">
        <span class="visual-kicker">${genreLabels[movie.genre] || "Жанр не указан"}${year ? ` · ${year} г.` : ""}</span>
        <span class="visual-number">${String(movie.id).padStart(2, "0")}</span>
        <span class="visual-power">${rating ? `⭐ ${rating}` : "Оценка н/д"}</span>
      </div>
      <div class="car-info">
        <p class="car-brand-label">${duration ? `Длительность: ${duration} мин.` : "Длительность не указана"}</p>
        <h2 class="car-title">${movie.title}</h2>
        <p class="car-description">${movie.longDesc || movie.desc || movie.description || "Описание пока не добавлено."}</p>
        <div class="movie-card-actions">
          <button class="details-btn" type="button" onclick="watchMovieTrailer(${movie.id})">▶ Смотреть трейлер</button>
          <button class="details-btn description-btn" type="button" onclick="openMovieDescription(${movie.id})">Описание фильма</button>
          <button class="details-btn watchlist-btn ${watchlist.includes(movie.id) ? "is-saved" : ""}" type="button" onclick="toggleWatchlist(${movie.id})" aria-pressed="${watchlist.includes(movie.id)}">${watchlist.includes(movie.id) ? "❤️ В избранном" : "♡ В избранное"}</button>
          <details class="movie-search-menu">
            <summary class="details-btn movie-search-toggle">🔍 Найти на...</summary>
            <div class="movie-search-options">
              <a class="movie-search-option" href="${getMegogoSearchUrl(movie)}" target="_blank" rel="noopener noreferrer">Найти фильм на Megogo ↗</a>
              <a class="movie-search-option" href="${getNetflixSearchUrl(movie)}" target="_blank" rel="noopener noreferrer">Найти фильм на Netflix ↗</a>
              <a class="movie-search-option" href="${getLegalViewingSearchUrl(movie)}" target="_blank" rel="noopener noreferrer">Найти легальный просмотр ↗</a>
            </div>
          </details>
        </div>
      </div>
    </article>
  `;
}

function appendMovieBatch(grid, movies) {
  if (!movies.length) return;
  const template = document.createElement("template");
  template.innerHTML = movies.map(renderMovieCard).join("");
  grid.append(template.content);
  grid.dispatchEvent(new CustomEvent("movies:batch-rendered", { detail: { movies } }));
}

function renderMovies(movies) {
  const grid = document.getElementById("moviesGrid");
  if (!grid) return;

  movieLoadObserver?.disconnect();
  movieLoadObserver = null;
  movieLoadSentinel?.remove();
  movieLoadSentinel = null;
  if (movieScrollFallback) {
    window.removeEventListener("scroll", movieScrollFallback);
    movieScrollFallback = null;
  }

  const count = document.getElementById("catalogMovieCount");
  if (count) count.textContent = `Найдено ${movies.length} фильмов · всего в базе: ${moviesDatabase.length}`;
  grid.replaceChildren();

  if (movies.length === 0) {
    grid.innerHTML = '<p class="empty-state">По вашему запросу фильмов не найдено.</p>';
    return;
  }

  let nextIndex = Math.min(MOVIE_INITIAL_BATCH_SIZE, movies.length);
  appendMovieBatch(grid, movies.slice(0, nextIndex));
  if (nextIndex >= movies.length) return;

  const loadNextBatch = () => {
    if (nextIndex >= movies.length) {
      movieLoadObserver?.disconnect();
      movieLoadSentinel?.remove();
      movieLoadSentinel = null;
      if (movieScrollFallback) {
        window.removeEventListener("scroll", movieScrollFallback);
        movieScrollFallback = null;
      }
      return;
    }
    const endIndex = Math.min(nextIndex + MOVIE_NEXT_BATCH_SIZE, movies.length);
    appendMovieBatch(grid, movies.slice(nextIndex, endIndex));
    nextIndex = endIndex;
  };

  movieLoadSentinel = document.createElement("div");
  movieLoadSentinel.className = "movie-load-sentinel";
  movieLoadSentinel.setAttribute("aria-hidden", "true");
  movieLoadSentinel.style.height = "1px";
  movieLoadSentinel.style.width = "100%";
  grid.insertAdjacentElement("afterend", movieLoadSentinel);

  if ("IntersectionObserver" in window) {
    movieLoadObserver = new IntersectionObserver(entries => {
      if (entries.some(entry => entry.isIntersecting)) loadNextBatch();
    }, { rootMargin: "400px 0px" });
    movieLoadObserver.observe(movieLoadSentinel);
  } else {
    movieScrollFallback = () => {
      if (movieLoadSentinel && movieLoadSentinel.getBoundingClientRect().top < window.innerHeight + 400) loadNextBatch();
    };
    window.addEventListener("scroll", movieScrollFallback, { passive: true });
    movieScrollFallback();
  }
}

// --- ПОДРОБНОЕ ОПИСАНИЕ И ТРЕЙЛЕРЫ ФИЛЬМОВ ---
function showMovieModal(movie, mode) {
  const modal = document.getElementById("movieModal");
  const title = document.getElementById("movieModalTitle");
  const content = document.getElementById("movieModalContent");
  const fallback = document.getElementById("movieModalFallback");
  const megogoLink = document.getElementById("movieMegogoLink");
  const netflixLink = document.getElementById("movieNetflixLink");
  const legalSearchLink = document.getElementById("movieLegalSearchLink");
  if (!modal || !title || !content || !fallback) return;

  title.textContent = movie.title;
  const setStreamingSearch = (link, destination, visible) => {
    if (!link) return;
    link.hidden = !visible;
    if (visible) link.href = destination;
    else link.removeAttribute("href");
  };
  const isDescription = mode === "description";
  setStreamingSearch(megogoLink, getMegogoSearchUrl(movie), isDescription);
  setStreamingSearch(netflixLink, getNetflixSearchUrl(movie), isDescription);
  setStreamingSearch(legalSearchLink, getLegalViewingSearchUrl(movie), isDescription);
  if (mode === "trailer") {
    if (movie.trailerId) {
      content.innerHTML = `<div class="trailer-frame"><iframe src="https://www.youtube-nocookie.com/embed/${movie.trailerId}?autoplay=0&playsinline=1&controls=1" title="Официальный трейлер фильма «${movie.title}»" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><p class="trailer-note">Если встроенный плеер не работает, откройте видео на YouTube.</p>`;
      fallback.href = `https://www.youtube.com/watch?v=${movie.trailerId}`;
      fallback.textContent = "Открыть трейлер на YouTube ↗";
    } else {
      content.innerHTML = `<p class="trailer-note">Для этого фильма нет встроенного трейлера. Найдите официальный трейлер на YouTube.</p>`;
      fallback.href = `https://www.youtube.com/results?search_query=${encodeURIComponent(`${movie.title} официальный трейлер`)}`;
      fallback.textContent = "Найти трейлер на YouTube ↗";
    }
    fallback.hidden = false;
  } else {
    const parsedYear = Number.parseInt(movie.year, 10);
    const year = Number.isInteger(parsedYear) && parsedYear >= 1888 && parsedYear <= new Date().getFullYear() ? parsedYear : null;
    const parsedRating = Number.parseFloat(movie.rating);
    const rating = Number.isFinite(parsedRating) && parsedRating > 0 && parsedRating <= 10 ? parsedRating.toFixed(1) : null;
    const parsedDuration = Number.parseFloat(String(movie.duration ?? "").replace(",", "."));
    const duration = Number.isFinite(parsedDuration) && parsedDuration > 0 ? parsedDuration : null;
    const meta = [
      year ? `<span>📅 ${year} год</span>` : "",
      rating ? `<span>⭐ ${rating}</span>` : "",
      duration ? `<span>⏱ ${duration} мин.</span>` : ""
    ].filter(Boolean).join("");
    content.innerHTML = `<div class="movie-description-meta">${meta}</div><p class="movie-long-description">${movie.longDesc || movie.desc || movie.description || "Описание пока не добавлено."}</p><p class="movie-description-note">Жанр: ${({ "sci-fi": "фантастика", action: "экшен", drama: "драма", comedy: "комедия", detective: "детектив", romance: "мелодрама" })[movie.genre] || "не указан"}.</p>`;
    const notes = document.createElement("section");
    notes.className = "director-notes";
    const notesTitle = document.createElement("h3");
    notesTitle.textContent = "Личные заметки";
    const notesLabel = document.createElement("label");
    notesLabel.className = "director-notes-label";
    notesLabel.htmlFor = "directorNotesInput";
    notesLabel.textContent = "Мысли после просмотра";
    const notesInput = document.createElement("textarea");
    notesInput.id = "directorNotesInput";
    notesInput.maxLength = 2000;
    notesInput.rows = 4;
    notesInput.placeholder = "Например: пересмотреть с папой или разобрать концовку";
    notesInput.setAttribute("aria-label", `Личная заметка к фильму «${movie.title}»`);
    const notesStatus = document.createElement("p");
    notesStatus.className = "director-notes-status";
    const notesKey = `cineNavigatorMovieNote:${movie.id}`;
    try {
      notesInput.value = localStorage.getItem(notesKey) || "";
      notesStatus.textContent = notesInput.value ? "Сохранённая заметка" : "Заметка сохранится автоматически в вашем профиле.";
    } catch (_) {
      notesStatus.textContent = "Хранилище заметок недоступно в этом режиме.";
      notesInput.disabled = true;
    }
    notesInput.addEventListener("input", () => {
      try {
        localStorage.setItem(notesKey, notesInput.value);
        notesStatus.textContent = "Заметка сохранена.";
      } catch (_) {
        notesStatus.textContent = "Не удалось сохранить заметку.";
      }
    });
    notes.append(notesTitle, notesLabel, notesInput, notesStatus);
    content.appendChild(notes);
    fallback.hidden = true;
    fallback.removeAttribute("href");
  }

  modal.classList.add("is-open");
  modal.setAttribute("aria-hidden", "false");
  document.body.classList.add("modal-open");
  modal.querySelector(".movie-modal-close").focus();
}

window.openMovieDescription = function (movieId) {
  const movie = moviesDatabase.find(item => item.id === movieId);
  if (movie) showMovieModal(movie, "description");
};

window.watchMovieTrailer = function (movieId) {
  const movie = moviesDatabase.find(item => item.id === movieId);
  if (!movie) return;
  showMovieModal(movie, "trailer");
};


window.closeMovieModal = function () {
  const modal = document.getElementById("movieModal");
  const content = document.getElementById("movieModalContent");
  if (!modal) return;
  modal.classList.remove("is-open");
  modal.setAttribute("aria-hidden", "true");
  document.body.classList.remove("modal-open");
  if (content) content.innerHTML = ""; // Останавливаем видео при закрытии окна.
};

document.addEventListener("keydown", event => {
  if (event.key === "Escape" && document.getElementById("movieModal")?.classList.contains("is-open")) {
    window.closeMovieModal();
  }
});

document.getElementById("movieModal")?.addEventListener("click", event => {
  if (event.target.id === "movieModal") window.closeMovieModal();
});

// --- УМНЫЙ ФИЛЬТР ПО ХРОНОМЕТРАЖУ ДО СНА ---
window.calculateTimeMovie = function () {
  const input = document.getElementById("timeLimitInput");
  const result = document.getElementById("timeResult");
  if (!input || !result) return;

  const limit = Number(input.value);

  if (!Number.isInteger(limit) || limit <= 0 || limit > 600) {
    result.textContent = "Укажи целое время от 1 до 600 минут.";
    result.className = "result-placeholder result-error";
    return;
  }

  // Берём только фильмы с полными данными, которые укладываются в лимит.
  const matches = moviesDatabase.filter(movie => isCompleteMovie(movie) && movie.duration <= limit);

  if (matches.length === 0) {
    result.textContent = `Не найдено фильмов с полными данными до ${limit} минут. Попробуй увеличить лимит.`;
    result.className = "result-placeholder result-error";
    return;
  }

  // Выбираем фильм с наивысшим рейтингом среди подходящих.
  matches.sort((a, b) => Number(b.rating) - Number(a.rating));
  const bestMovie = matches[0];

  result.textContent = `⏱ Из ${matches.length} фильмов с полными данными подходят под лимит. Лучший выбор: ${formatMovieRecommendation(bestMovie)} Ты успеешь посмотреть его до полуночи!`;
  result.className = "result-placeholder result-success";
};

// --- ИНТЕРАКТИВНЫЙ ПОДБОР КИНО ПОД ЕДУ ---
window.triggerFoodMovie = function () {
  const select = document.getElementById("foodSelect");
  const result = document.getElementById("foodResult");
  if (!select || !result) return;

  const chosenFood = select.value;
  const matches = moviesDatabase.filter(movie => movie.food === chosenFood && isCompleteMovie(movie));
  if (matches.length === 0) {
    result.textContent = "Не найдено подходящих фильмов с полными данными. Попробуй другой перекус.";
    result.className = "result-placeholder result-error";
    return;
  }

  // Выдаем случайный вариант из совпадений с заполненными данными.
  const randomMovie = matches[Math.floor(Math.random() * matches.length)];
  result.textContent = `🍽 Под твой ужин подходит фильм: ${formatMovieRecommendation(randomMovie)} ${getMovieDescription(randomMovie)}`;
  result.className = "result-placeholder result-success";
};

// --- УПРАВЛЕНИЕ МОДАЛКОЙ ПРИВЕТСТВИЯ ---
window.closeWelcomeModal = function () {
  const modal = document.getElementById("welcomeModal");
  const container = document.getElementById("mainContainer");
  if (modal) modal.style.display = "none";
  if (container) container.style.display = "block";
  applyMovieFilters();
};

